hooks.command:
echo "$TOOL_INPUT" | python3 -c "
import sys, json
try:
    data = json.load(sys.stdin)
    cmd = data.get('command', '')
    dangerous = ['rm -rf /', 'rm -rf ~', 'rm -rf *', 'rm -rf .', ':(){', 'mkfs', 'dd if=', '> /dev/sd', 'chmod -R 777 /', 'curl|sh', 'wget|sh', 'curl|bash', 'wget|bash']
    for d in dangerous:
        if d in cmd:
            print(f'BLOCKED: dangerous command detected: {d}')
            sys.exit(1)
    if 'rm -rf' in cmd and ('eagle/' in cmd or 'data/' in cmd or '.claude/' in cmd):
        print(f'BLOCKED: rm -rf on protected directory')
        sys.exit(1)
except Exception as e:
    pass
"
